import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print(-1)
        return

    n = int(data[0])
    if n == 0:
        print(-1)
        return

    arr = list(map(int, data[1:1+n]))
    k = int(data[1+n])

    seen = set()
    pairs = set()

    for num in arr:
        complement = k - num
        if complement in seen:
            pair = (min(complement, num), max(complement, num))
            pairs.add(pair)
        seen.add(num)

    if not pairs:
        print(-1)
    else:
        pairs_sorted = sorted(pairs, reverse=True)
        for p in pairs_sorted:
            print("({}, {})".format(p[0], p[1]))

if __name__ == "__main__":
    main()
